mapper.sql:
WHERE is_deleted = 0

    AND emp_code LIKE CONCAT('%', #{q.empCode}, '%')


    AND name LIKE CONCAT('%', #{q.name}, '%')


    AND dept_id = #{q.deptId}


    AND status = #{q.status}


    AND id = #{q.employeeId}

mapper.select:
SELECT  FROM hr_employee
WHERE is_deleted = 0 AND status = #{status}
ORDER BY id ASC
